package com.shrija.workflow.controller; import com.shrija.workflow.dto.*; import com.shrija.workflow.service.WorkflowConversationService; import jakarta.validation.Valid; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/workflow") public class WorkflowController { private final WorkflowConversationService service; public WorkflowController(WorkflowConversationService service){this.service=service;} @PostMapping("/chat") public ResponseEntity<WorkflowChatResponse> chat(@Valid @RequestBody WorkflowChatRequest r){var x=service.converse(r);return ResponseEntity.ok(new WorkflowChatResponse(x.sessionId(),x.responseText()));} }
